-- Reviewed senior batch 023; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4831,"word":"wary","meaning":"小心的","example":"The wary visitor checked the old steps before moving forward.","example_zh":"謹慎訪客前進前先檢查老階梯。","original_meaning":"小心的","original_example":"Be wary of strangers.","original_example_zh":"對陌生人要保持警惕。"},{"source_id":4832,"word":"whimsical","meaning":"異想天開的","example":"The whimsical sculpture looked like a bird carrying a tiny house.","example_zh":"異想天開雕塑像一隻背著小屋的鳥。","original_meaning":"異想天開的","original_example":"A whimsical idea.","original_example_zh":"一個奇思妙想。"},{"source_id":4833,"word":"wholesome","meaning":"健全的；有益健康的","example":"The wholesome meal included vegetables, rice, and fruit.","example_zh":"健康餐點包含蔬菜、米飯與水果。","original_meaning":"健全的","original_example":"Wholesome food.","original_example_zh":"健康食品。"},{"source_id":4834,"word":"withstand","meaning":"承受","example":"The strong bridge model could withstand the added weight.","example_zh":"堅固模型橋能承受增加的重量。","original_meaning":"承受","original_example":"Withstand pressure.","original_example_zh":"承受壓力。"},{"source_id":4835,"word":"zealous","meaning":"熱情的","example":"The zealous volunteers arrived early to prepare the reading festival.","example_zh":"熱情志工提早到場準備閱讀節。","original_meaning":"熱情的","original_example":"A zealous advocate.","original_example_zh":"一位熱忱的倡導者。"},{"source_id":4836,"word":"accustom","meaning":"使習慣","example":"The short rehearsals helped accustom the students to performing on stage.","example_zh":"短排練幫學生習慣上臺演出。","original_meaning":"使習慣","original_example":"Accustom to the climate.","original_example_zh":"適應氣候。"},{"source_id":4837,"word":"adept","meaning":"熟練的","example":"She was adept at fitting the tiny wooden pieces together.","example_zh":"她熟練地接合微小木零件。","original_meaning":"熟練的","original_example":"Adept at cooking.","original_example_zh":"擅長烹飪。"},{"source_id":4838,"word":"admonish","meaning":"告誡","example":"The coach will gently admonish the team to check every helmet.","example_zh":"教練會溫和告誡隊員檢查每頂安全帽。","original_meaning":"告誡","original_example":"Admonish the students.","original_example_zh":"訓誡學生。"},{"source_id":4839,"word":"adorn","meaning":"裝飾","example":"The students used paper leaves to adorn the library entrance.","example_zh":"學生用紙葉裝飾圖書館入口。","original_meaning":"裝飾","original_example":"Adorn the room.","original_example_zh":"裝飾房間。"},{"source_id":4840,"word":"affable","meaning":"和藹的","example":"The affable guide made the visitors comfortable asking questions.","example_zh":"和藹導覽員讓訪客自在提問。","original_meaning":"和藹的","original_example":"An affable person.","original_example_zh":"一位和藹可親的人。"},{"source_id":4841,"word":"aghast","meaning":"驚駭的","example":"The students were aghast when they saw the ruined model.","example_zh":"學生看到損壞模型時驚駭不已。","original_meaning":"驚駭的","original_example":"She stood aghast.","original_example_zh":"她驚呆了。"},{"source_id":4842,"word":"agitate","meaning":"鼓動","example":"The residents began to agitate for a safer crossing.","example_zh":"居民開始鼓動爭取更安全的行人穿越道。","original_meaning":"鼓動","original_example":"Agitate for reform.","original_example_zh":"為改革而奮鬥。"},{"source_id":4843,"word":"agonize","meaning":"苦惱","example":"She began to agonize over which painting to submit.","example_zh":"她開始為該提交哪幅畫苦惱。","original_meaning":"苦惱","original_example":"Agonize over a decision.","original_example_zh":"為某個決定而苦惱。"},{"source_id":4844,"word":"akin","meaning":"類似的","example":"The leaf's pattern was akin to the branches of a small tree.","example_zh":"葉片紋理類似小樹枝幹。","original_meaning":"類似的","original_example":"Akin to madness.","original_example_zh":"近乎瘋狂。"},{"source_id":4845,"word":"allegiance","meaning":"忠誠","example":"The story explored a knight's allegiance to the kingdom.","example_zh":"故事探討騎士對王國的忠誠。","original_meaning":"忠誠","original_example":"Pledge allegiance.","original_example_zh":"宣誓效忠。"},{"source_id":4846,"word":"aloof","meaning":"冷漠的","example":"The aloof character stayed apart from the cheerful group.","example_zh":"冷漠角色與歡樂人群保持距離。","original_meaning":"冷漠的","original_example":"Remain aloof.","original_example_zh":"保持超然。"},{"source_id":4847,"word":"amenable","meaning":"順從的；願配合的","example":"The club was amenable to changing the rehearsal schedule.","example_zh":"社團願意配合調整排練時間。","original_meaning":"順從的","original_example":"Amenable to change.","original_example_zh":"願意接受改變。"},{"source_id":4848,"word":"amicable","meaning":"友善的","example":"The discussion ended with an amicable agreement.","example_zh":"討論以友善協議結束。","original_meaning":"友善的","original_example":"An amicable settlement.","original_example_zh":"友好的和解。"},{"source_id":4849,"word":"antithesis","meaning":"對立面","example":"The noisy market was the antithesis of the quiet library.","example_zh":"喧鬧市集與安靜圖書館恰好相反。","original_meaning":"對立面","original_example":"The antithesis of freedom.","original_example_zh":"自由的對立面。"},{"source_id":4850,"word":"apprehend","meaning":"逮捕","example":"The police managed to apprehend the suspect without anyone being hurt.","example_zh":"警方成功逮捕嫌疑人，無人受傷。","original_meaning":"逮捕","original_example":"Apprehend the thief.","original_example_zh":"逮捕小偷。"},{"source_id":4851,"word":"ardor","meaning":"熱忱","example":"Her ardor for music kept her practicing patiently.","example_zh":"她對音樂的熱忱使她耐心練習。","original_meaning":"熱忱","original_example":"Youthful ardor.","original_example_zh":"青春的熱情。"},{"source_id":4852,"word":"arid","meaning":"乾燥的","example":"The arid landscape had dry soil and very few plants.","example_zh":"乾燥地景有乾土與稀少植物。","original_meaning":"乾燥的","original_example":"An arid desert.","original_example_zh":"一片乾旱的沙漠。"},{"source_id":4853,"word":"arsenal","meaning":"武器庫","example":"The museum preserved part of the old arsenal as a historic exhibit.","example_zh":"博物館保存部分舊武器庫作為歷史展示。","original_meaning":"武器庫","original_example":"A nuclear arsenal.","original_example_zh":"核武庫。"},{"source_id":4854,"word":"ascend","meaning":"上升","example":"The hikers began to ascend the gentle hillside trail.","example_zh":"健行者開始沿平緩山坡步道上升。","original_meaning":"上升","original_example":"Ascend the mountain.","original_example_zh":"攀登高山。"},{"source_id":4855,"word":"asphalt","meaning":"瀝青","example":"The workers repaired the asphalt on the empty road.","example_zh":"工人修補空道路的瀝青。","original_meaning":"瀝青","original_example":"An asphalt road.","original_example_zh":"一條瀝青路。"},{"source_id":4856,"word":"assail","meaning":"攻擊","example":"Strong waves began to assail the stone wall.","example_zh":"強浪開始衝擊石牆。","original_meaning":"攻擊","original_example":"Assailed by doubts.","original_example_zh":"被疑慮所困擾。"},{"source_id":4857,"word":"atone","meaning":"贖罪；彌補過失","example":"He tried to atone for the mistake by helping repair the model.","example_zh":"他協助修模型，試著彌補過失。","original_meaning":"贖罪","original_example":"Atone for sins.","original_example_zh":"贖罪。"},{"source_id":4858,"word":"atrophy","meaning":"萎縮","example":"The anatomy model illustrated muscle atrophy.","example_zh":"解剖模型呈現肌肉萎縮。","original_meaning":"萎縮","original_example":"Muscle atrophy.","original_example_zh":"肌肉萎縮。"},{"source_id":4859,"word":"attest","meaning":"證實","example":"The old photographs could attest to the bridge's original shape.","example_zh":"老照片能證實橋梁最初形狀。","original_meaning":"證實","original_example":"Attest to the truth.","original_example_zh":"證明事實。"},{"source_id":4860,"word":"audacious","meaning":"大膽的","example":"The audacious design combined a garden with a rooftop library.","example_zh":"大膽設計把花園與屋頂圖書館結合。","original_meaning":"大膽的","original_example":"An audacious plan.","original_example_zh":"一個大膽的計劃。"},{"source_id":4861,"word":"avenge","meaning":"報仇","example":"The novel followed a character determined to avenge an old wrong.","example_zh":"小說追隨一位決心報復舊日不公的角色。","original_meaning":"報仇","original_example":"Avenge the fallen.","original_example_zh":"為犧牲者報仇。"},{"source_id":4862,"word":"avow","meaning":"聲明","example":"The speaker chose to avow her support for the restoration project.","example_zh":"講者選擇公開聲明支持修復計畫。","original_meaning":"聲明","original_example":"Avow innocence.","original_example_zh":"聲稱無辜。"},{"source_id":4863,"word":"banish","meaning":"放逐","example":"The tale described a ruler who tried to banish his honest adviser.","example_zh":"故事描寫企圖放逐忠實顧問的統治者。","original_meaning":"放逐","original_example":"Banished from the kingdom.","original_example_zh":"被逐出王國。"},{"source_id":4864,"word":"bask","meaning":"曬太陽","example":"The turtles began to bask on a warm rock.","example_zh":"烏龜開始在溫暖石頭上曬太陽。","original_meaning":"曬太陽","original_example":"Bask in the sun.","original_example_zh":"沐浴在陽光下。"},{"source_id":4865,"word":"beckon","meaning":"招手","example":"The guide used a friendly gesture to beckon the visitors closer.","example_zh":"導覽員友善招手，請訪客靠近。","original_meaning":"招手","original_example":"She beckoned to me.","original_example_zh":"她向我招手。"},{"source_id":4866,"word":"befriend","meaning":"交友","example":"The students decided to befriend the newcomer.","example_zh":"學生決定與新來同學交朋友。","original_meaning":"交友","original_example":"Befriend a stranger.","original_example_zh":"結交一位陌生人。"},{"source_id":4867,"word":"beguile","meaning":"迷惑；吸引","example":"The storyteller could beguile the audience with her vivid descriptions.","example_zh":"說書人能用生動描述迷住聽眾。","original_meaning":"迷惑","original_example":"Beguiled by her charm.","original_example_zh":"被她的魅力所迷住。"},{"source_id":4868,"word":"behold","meaning":"注視","example":"We stopped to behold the waterfall in the morning light.","example_zh":"我們停下來注視晨光中的瀑布。","original_meaning":"注視","original_example":"Behold the sunset.","original_example_zh":"欣賞日落。"},{"source_id":4869,"word":"bequeath","meaning":"遺贈","example":"The teacher chose to bequeath her books to the school library.","example_zh":"老師選擇把書籍遺贈學校圖書館。","original_meaning":"遺贈","original_example":"Bequeath a fortune.","original_example_zh":"遺贈一筆財富。"},{"source_id":4870,"word":"bereave","meaning":"喪親","example":"The accident bereaved the family of a loved one.","example_zh":"那場事故讓家人失去摯愛。","original_meaning":"喪親","original_example":"A bereaved family.","original_example_zh":"一個喪親的家庭。"},{"source_id":4871,"word":"bestow","meaning":"授予","example":"The school will bestow an award on the volunteers.","example_zh":"學校將授予志工獎項。","original_meaning":"授予","original_example":"Bestow an honor.","original_example_zh":"授予榮譽。"},{"source_id":4872,"word":"bizarre","meaning":"奇異的","example":"The bizarre sculpture combined a fish with a clock.","example_zh":"奇異雕塑把魚與時鐘結合。","original_meaning":"奇異的","original_example":"A bizarre incident.","original_example_zh":"一樁離奇的事件。"},{"source_id":4873,"word":"blunder","meaning":"失誤","example":"The missing support was a serious blunder in the design.","example_zh":"漏掉支撐，是設計中的嚴重失誤。","original_meaning":"失誤","original_example":"A terrible blunder.","original_example_zh":"一個可怕的失誤。"},{"source_id":4874,"word":"boisterous","meaning":"喧鬧的","example":"The boisterous fans cheered after the final song.","example_zh":"喧鬧樂迷在最後一首歌後歡呼。","original_meaning":"喧鬧的","original_example":"A boisterous crowd.","original_example_zh":"喧鬧的人群。"},{"source_id":4875,"word":"brazen","meaning":"厚顏的","example":"The character's brazen attempt to skip the queue upset the others.","example_zh":"角色厚顏插隊的行為惹其他人不悅。","original_meaning":"厚顏的","original_example":"A brazen lie.","original_example_zh":"一個厚顏無恥的謊言。"},{"source_id":4876,"word":"bristle","meaning":"發怒","example":"He began to bristle at the unfair accusation.","example_zh":"他因不公平指控開始發怒。","original_meaning":"發怒","original_example":"Bristle at the insult.","original_example_zh":"對侮辱感到憤怒。"},{"source_id":4877,"word":"bungle","meaning":"搞砸","example":"The character managed to bungle the simple repair.","example_zh":"那個角色竟把簡單修理搞砸。","original_meaning":"搞砸","original_example":"Bungle the job.","original_example_zh":"搞砸了這份工作。"},{"source_id":4878,"word":"buoyancy","meaning":"浮力","example":"The experiment compared the buoyancy of two small boats.","example_zh":"實驗比較兩艘小船的浮力。","original_meaning":"浮力","original_example":"The buoyancy of water.","original_example_zh":"水的浮力。"},{"source_id":4879,"word":"cache","meaning":"隱藏處；珍藏","example":"The archive held a cache of old photographs.","example_zh":"檔案館保存一批老照片珍藏。","original_meaning":"隱藏處","original_example":"A weapons cache.","original_example_zh":"武器庫。"},{"source_id":4880,"word":"cajole","meaning":"哄騙；哄勸","example":"She tried to cajole her friend into joining the choir.","example_zh":"她試著哄勸朋友加入合唱團。","original_meaning":"哄騙","original_example":"Cajole into agreeing.","original_example_zh":"哄哄哄地說服對方同意。"},{"source_id":4881,"word":"capitulate","meaning":"投降","example":"The fictional ruler agreed to capitulate after peace negotiations.","example_zh":"虛構統治者在和平談判後同意投降。","original_meaning":"投降","original_example":"Forced to capitulate.","original_example_zh":"被迫投降。"},{"source_id":4882,"word":"capricious","meaning":"善變的","example":"The capricious character kept changing the festival plans.","example_zh":"善變角色不斷修改節慶計畫。","original_meaning":"善變的","original_example":"A capricious boss.","original_example_zh":"一位任性的老闆。"},{"source_id":4883,"word":"caste","meaning":"種姓","example":"The sociology exhibit examined how caste shaped social roles.","example_zh":"社會學展覽探討種姓如何影響社會角色。","original_meaning":"種姓","original_example":"The caste system.","original_example_zh":"種姓制度。"},{"source_id":4884,"word":"catapult","meaning":"彈射","example":"The spring could catapult the foam ball into the soft basket.","example_zh":"彈簧能把泡棉球彈射進柔軟籃子。","original_meaning":"彈射","original_example":"Catapulted to fame.","original_example_zh":"一夕成名。"},{"source_id":4885,"word":"causality","meaning":"因果關係","example":"The class investigated causality by changing one part of the model.","example_zh":"班上改變模型一個部分，探究因果關係。","original_meaning":"因果關係","original_example":"The principle of causality.","original_example_zh":"因果律。"},{"source_id":4886,"word":"cerebral","meaning":"大腦的","example":"The cerebral model showed the brain's major regions.","example_zh":"大腦模型展示主要區域。","original_meaning":"大腦的","original_example":"A cerebral approach.","original_example_zh":"一種深思熟慮的做法。"},{"source_id":4887,"word":"chagrin","meaning":"懊惱","example":"To her chagrin, she had left the music score at home.","example_zh":"令她懊惱的是，她把樂譜忘在家裡。","original_meaning":"懊惱","original_example":"Much to my chagrin.","original_example_zh":"令我深感遺憾。"},{"source_id":4888,"word":"chasm","meaning":"裂縫","example":"The trail offered a view of a deep chasm.","example_zh":"步道能看見深裂谷。","original_meaning":"裂縫","original_example":"A deep chasm.","original_example_zh":"一道深淵。"},{"source_id":4889,"word":"cherish","meaning":"珍惜","example":"She continued to cherish the old violin from her grandmother.","example_zh":"她持續珍惜祖母留下的老提琴。","original_meaning":"珍惜","original_example":"Cherish the moment.","original_example_zh":"珍惜當下。"},{"source_id":4890,"word":"chivalry","meaning":"騎士精神；禮讓","example":"The traveler's chivalry showed when he held the door for another visitor.","example_zh":"那位旅人替另一位訪客扶門，展現禮讓精神。","original_meaning":"騎士精神","original_example":"An act of chivalry.","original_example_zh":"騎士精神。"},{"source_id":4891,"word":"circumspect","meaning":"謹慎的","example":"The circumspect guide checked the route before leading the group.","example_zh":"謹慎嚮導帶隊前先檢查路線。","original_meaning":"謹慎的","original_example":"Be circumspect.","original_example_zh":"謹慎行事。"},{"source_id":4892,"word":"cite","meaning":"引用","example":"She will cite a short passage from the book in her report.","example_zh":"她會在報告引用書中一小段。","original_meaning":"引用","original_example":"Cite the source.","original_example_zh":"引用來源。"},{"source_id":4893,"word":"climactic","meaning":"情節達到高峰的","example":"The climactic scene showed the team finally completing the bridge.","example_zh":"劇情達到高峰的一幕呈現團隊終於完成橋梁。","original_meaning":"高潮的","original_example":"The climactic scene.","original_example_zh":"高潮場面。"},{"source_id":4894,"word":"coarse","meaning":"粗糙的","example":"The coarse fabric felt rough beside the smooth cloth.","example_zh":"粗布與平滑布料相比觸感粗糙。","original_meaning":"粗糙的","original_example":"Coarse fabric.","original_example_zh":"粗糙的布料。"},{"source_id":4895,"word":"coax","meaning":"哄勸","example":"The volunteer tried to coax the shy puppy out of its carrier.","example_zh":"志工試著哄勸害羞小狗走出提籠。","original_meaning":"哄勸","original_example":"Coax a child.","original_example_zh":"哄哄孩子。"},{"source_id":4896,"word":"coexistence","meaning":"共存","example":"The wetland showed the peaceful coexistence of many species.","example_zh":"濕地展現多種物種和平共存。","original_meaning":"共存","original_example":"Peaceful coexistence.","original_example_zh":"和平共存。"},{"source_id":4897,"word":"cogent","meaning":"有說服力的","example":"Her cogent argument persuaded the group to add a support.","example_zh":"她有說服力的論證讓小組決定增加支撐。","original_meaning":"有說服力的","original_example":"A cogent argument.","original_example_zh":"一個有力的論點。"},{"source_id":4898,"word":"commend","meaning":"表揚","example":"The principal will commend the students for helping restore the library.","example_zh":"校長將表揚協助修復圖書館的學生。","original_meaning":"表揚","original_example":"Commend for bravery.","original_example_zh":"表揚勇氣。"},{"source_id":4899,"word":"condescend","meaning":"屈尊；以高姿態待人","example":"The expert refused to condescend to the beginners.","example_zh":"專家拒絕以高高在上態度對待新手。","original_meaning":"屈尊","original_example":"Condescend to reply.","original_example_zh":"請惠賜回覆。"},{"source_id":4900,"word":"confide","meaning":"吐露","example":"She chose to confide her worries to a trusted mentor.","example_zh":"她選擇向信任導師吐露憂慮。","original_meaning":"吐露","original_example":"Confide in a friend.","original_example_zh":"向朋友傾訴。"},{"source_id":4901,"word":"conjure","meaning":"喚起","example":"The old melody could conjure memories of childhood.","example_zh":"古老旋律能喚起童年回憶。","original_meaning":"喚起","original_example":"Conjure up memories.","original_example_zh":"喚起回憶。"},{"source_id":4902,"word":"connote","meaning":"含意","example":"The open window could connote freedom in the poem.","example_zh":"敞開窗戶在詩中可能含有自由之意。","original_meaning":"含意","original_example":"The word connotes danger.","original_example_zh":"這個詞暗示著危險。"},{"source_id":4903,"word":"conscientious","meaning":"認真的","example":"The conscientious student checked every tool before leaving.","example_zh":"認真學生離開前檢查每件工具。","original_meaning":"認真的","original_example":"A conscientious student.","original_example_zh":"一位盡責的學生。"},{"source_id":4904,"word":"construe","meaning":"解釋","example":"The reader could construe the ending as a sign of hope.","example_zh":"讀者可把結局解釋為希望的象徵。","original_meaning":"解釋","original_example":"Construed as hostile.","original_example_zh":"被解讀為敵意。"},{"source_id":4905,"word":"consummate","meaning":"完美的；技藝高超的","example":"The consummate musician handled the difficult passage with ease.","example_zh":"技藝完美的音樂家輕鬆處理困難樂段。","original_meaning":"完美的","original_example":"A consummate professional.","original_example_zh":"一位技藝精湛的專業人士。"},{"source_id":4906,"word":"contrive","meaning":"設法","example":"The students managed to contrive a useful device from spare parts.","example_zh":"學生設法用備用零件做出實用裝置。","original_meaning":"設法","original_example":"Contrive a plan.","original_example_zh":"構思一個計劃。"},{"source_id":4907,"word":"convivial","meaning":"歡樂的","example":"The convivial gathering brought old and new volunteers together.","example_zh":"歡樂聚會讓新舊志工相聚。","original_meaning":"歡樂的","original_example":"A convivial atmosphere.","original_example_zh":"熱鬧的氣氛。"},{"source_id":4908,"word":"cordial","meaning":"親切的","example":"The visitors received a cordial welcome at the village library.","example_zh":"訪客在村莊圖書館受到親切歡迎。","original_meaning":"親切的","original_example":"A cordial welcome.","original_example_zh":"熱情的歡迎。"},{"source_id":4909,"word":"corrode","meaning":"腐蝕","example":"Years of damp weather could corrode the iron gate.","example_zh":"多年潮濕天氣會腐蝕鐵門。","original_meaning":"腐蝕","original_example":"Acid corrodes metal.","original_example_zh":"酸會腐蝕金屬。"},{"source_id":4910,"word":"covet","meaning":"垂涎","example":"The story's character began to covet the beautiful trophy.","example_zh":"故事角色開始垂涎漂亮獎盃。","original_meaning":"垂涎","original_example":"Covet wealth.","original_example_zh":"貪圖財富。"},{"source_id":4911,"word":"creed","meaning":"信條","example":"The club's creed emphasized honesty and cooperation.","example_zh":"社團信條強調誠實與合作。","original_meaning":"信條","original_example":"A personal creed.","original_example_zh":"個人的信條。"},{"source_id":4912,"word":"cumbersome","meaning":"笨重的","example":"The cumbersome model was difficult to carry through the doorway.","example_zh":"笨重模型難以搬過門口。","original_meaning":"笨重的","original_example":"A cumbersome process.","original_example_zh":"繁瑣的過程。"},{"source_id":4913,"word":"curate","meaning":"策展","example":"The students helped curate an exhibit about the town's river.","example_zh":"學生協助策劃城鎮河川展。","original_meaning":"策展","original_example":"Curate an exhibition.","original_example_zh":"策劃展覽。"},{"source_id":4914,"word":"decipher","meaning":"破譯","example":"The historian tried to decipher the faded handwriting.","example_zh":"歷史學家試著辨識褪色手寫字。","original_meaning":"破譯","original_example":"Decipher the code.","original_example_zh":"破譯密碼。"},{"source_id":4915,"word":"decorum","meaning":"禮節","example":"The visitors maintained decorum during the solemn ceremony.","example_zh":"訪客在莊嚴儀式中保持禮節。","original_meaning":"禮節","original_example":"Maintain decorum.","original_example_zh":"保持儀態。"},{"source_id":4916,"word":"defer","meaning":"推遲","example":"The organizers decided to defer the outdoor concert until the weather improved.","example_zh":"主辦者決定等天氣轉好再辦戶外音樂會。","original_meaning":"推遲","original_example":"Defer the decision.","original_example_zh":"推遲決定。"},{"source_id":4917,"word":"degrade","meaning":"降低","example":"Pollution could degrade the quality of the river water.","example_zh":"污染可能降低河水品質。","original_meaning":"降低","original_example":"Degrade the quality.","original_example_zh":"降低品質。"},{"source_id":4918,"word":"demote","meaning":"降職","example":"The board voted to demote the manager after reviewing the errors.","example_zh":"董事會檢視錯誤後表決降低經理職位。","original_meaning":"降職","original_example":"Demoted to a lower rank.","original_example_zh":"被降級。"},{"source_id":4919,"word":"deplore","meaning":"強烈反對","example":"The community continued to deplore the destruction of the old trees.","example_zh":"社區持續強烈反對破壞老樹。","original_meaning":"強烈反對","original_example":"Deplore violence.","original_example_zh":"譴責暴力。"},{"source_id":4920,"word":"depose","meaning":"罷黜","example":"The historical account described how the council tried to depose the ruler.","example_zh":"歷史記述描述議會如何試圖罷黜統治者。","original_meaning":"罷黜","original_example":"Depose the dictator.","original_example_zh":"推翻獨裁者。"},{"source_id":4921,"word":"deprecate","meaning":"反對","example":"The speaker deprecated the needless waste of materials.","example_zh":"講者反對不必要的材料浪費。","original_meaning":"反對","original_example":"Deprecate the use of.","original_example_zh":"譴責使用。"},{"source_id":4922,"word":"descend","meaning":"下降","example":"The hikers began to descend the gentle forest trail.","example_zh":"健行者開始沿平緩林道下行。","original_meaning":"下降","original_example":"Descend the stairs.","original_example_zh":"走下樓梯。"},{"source_id":4923,"word":"despise","meaning":"鄙視","example":"The honest character came to despise the ruler's cruelty.","example_zh":"正直角色開始鄙視統治者的殘酷。","original_meaning":"鄙視","original_example":"Despise dishonesty.","original_example_zh":"鄙視不誠實。"},{"source_id":4924,"word":"destitute","meaning":"一貧如洗的","example":"The charity provided basic supplies to destitute families.","example_zh":"慈善團體向一貧如洗家庭提供基本物資。","original_meaning":"一貧如洗的","original_example":"Left destitute.","original_example_zh":"變得一貧如洗。"},{"source_id":4925,"word":"detach","meaning":"分離","example":"We could detach the small wheel before repairing the model.","example_zh":"修模型前，我們能拆下小輪子。","original_meaning":"分離","original_example":"Detach the cable.","original_example_zh":"拔掉電纜。"},{"source_id":4926,"word":"devious","meaning":"狡猾的","example":"The devious character concealed his plan from the other villagers.","example_zh":"狡猾角色向其他村民隱藏計畫。","original_meaning":"狡猾的","original_example":"A devious scheme.","original_example_zh":"陰險的計謀。"},{"source_id":4927,"word":"devour","meaning":"吞噬","example":"The hungry hikers began to devour their sandwiches.","example_zh":"飢餓健行者開始大口吃三明治。","original_meaning":"吞噬","original_example":"Devour a book.","original_example_zh":"如飢似渴地閱讀。"},{"source_id":4928,"word":"diction","meaning":"措辭","example":"Her careful diction made every line of the speech clear.","example_zh":"她謹慎措辭，讓演說每一句都清楚。","original_meaning":"措辭","original_example":"Clear diction.","original_example_zh":"發音清晰。"},{"source_id":4929,"word":"diffident","meaning":"缺乏自信的","example":"The diffident student spoke more confidently after encouragement.","example_zh":"缺乏自信學生在鼓勵後發言更有信心。","original_meaning":"缺乏自信的","original_example":"A diffident manner.","original_example_zh":"膽怯的態度。"},{"source_id":4930,"word":"dignify","meaning":"使高貴；賦予尊嚴","example":"The ceremony helped dignify the work of the volunteers.","example_zh":"典禮幫助向志工工作致敬、賦予尊嚴。","original_meaning":"使高貴","original_example":"Dignify the occasion.","original_example_zh":"為場合增添莊重感。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-wary-01-v1","level":"senior","word":"wary","sort_order":1,"sense":"小心的","alt_zh":"成年導覽員陪高中生在穩固入口仔細查看舊階梯，危險區已封閉。","example":"The wary visitor checked the old steps before moving forward.","example_zh":"謹慎訪客前進前先檢查老階梯。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wary-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-whimsical-01-v1","level":"senior","word":"whimsical","sort_order":1,"sense":"異想天開的","alt_zh":"高中生在美術館欣賞可愛原創鳥與小屋雕塑，成年導覽員解說。","example":"The whimsical sculpture looked like a bird carrying a tiny house.","example_zh":"異想天開雕塑像一隻背著小屋的鳥。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/whimsical-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-wholesome-01-v1","level":"senior","word":"wholesome","sort_order":1,"sense":"健全的；有益健康的","alt_zh":"高中生與成年老師在明亮餐廳享用均衡日常餐點，無體型評價。","example":"The wholesome meal included vegetables, rice, and fruit.","example_zh":"健康餐點包含蔬菜、米飯與水果。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wholesome-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-withstand-01-v1","level":"senior","word":"withstand","sort_order":1,"sense":"承受","alt_zh":"成年老師監督高中生在木模型橋放小砝碼，橋保持平直穩固。","example":"The strong bridge model could withstand the added weight.","example_zh":"堅固模型橋能承受增加的重量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/withstand-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-zealous-01-v1","level":"senior","word":"zealous","sort_order":1,"sense":"熱情的","alt_zh":"高中與成年志工在校園禮堂興致勃勃布置書攤。","example":"The zealous volunteers arrived early to prepare the reading festival.","example_zh":"熱情志工提早到場準備閱讀節。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/zealous-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-accustom-01-v1","level":"senior","word":"accustom","sort_order":1,"sense":"使習慣","alt_zh":"成年音樂老師耐心陪高中生在小舞臺練習，神情逐漸自信。","example":"The short rehearsals helped accustom the students to performing on stage.","example_zh":"短排練幫學生習慣上臺演出。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/accustom-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-adept-01-v1","level":"senior","word":"adept","sort_order":1,"sense":"熟練的","alt_zh":"高中女生在成年工藝老師旁精準組裝細小木模型。","example":"She was adept at fitting the tiny wooden pieces together.","example_zh":"她熟練地接合微小木零件。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/adept-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-admonish-01-v1","level":"senior","word":"admonish","sort_order":1,"sense":"告誡","alt_zh":"成年教練在騎行前提醒高中生逐一檢查安全帽，車仍停妥。","example":"The coach will gently admonish the team to check every helmet.","example_zh":"教練會溫和告誡隊員檢查每頂安全帽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/admonish-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-adorn-01-v1","level":"senior","word":"adorn","sort_order":1,"sense":"裝飾","alt_zh":"高中志工與成年館員在安全低處布置原創彩色紙葉。","example":"The students used paper leaves to adorn the library entrance.","example_zh":"學生用紙葉裝飾圖書館入口。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/adorn-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-affable-01-v1","level":"senior","word":"affable","sort_order":1,"sense":"和藹的","alt_zh":"成年導覽員在博物館微笑回應高中生好奇問題。","example":"The affable guide made the visitors comfortable asking questions.","example_zh":"和藹導覽員讓訪客自在提問。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/affable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-aghast-01-v1","level":"senior","word":"aghast","sort_order":1,"sense":"驚駭的","alt_zh":"高中團隊驚訝看桌上倒塌的輕木模型橋，成年老師溫和安慰，無傷害。","example":"The students were aghast when they saw the ruined model.","example_zh":"學生看到損壞模型時驚駭不已。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aghast-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-agitate-01-v1","level":"senior","word":"agitate","sort_order":1,"sense":"鼓動","alt_zh":"成年居民與交通官員在社區會議和平討論路口模型，無標語。","example":"The residents began to agitate for a safer crossing.","example_zh":"居民開始鼓動爭取更安全的行人穿越道。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/agitate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-agonize-01-v1","level":"senior","word":"agonize","sort_order":1,"sense":"苦惱","alt_zh":"高中美術學生與成年老師在兩幅完成畫作前認真思索。","example":"She began to agonize over which painting to submit.","example_zh":"她開始為該提交哪幅畫苦惱。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/agonize-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-akin-01-v1","level":"senior","word":"akin","sort_order":1,"sense":"類似的","alt_zh":"高中生與成年老師在自然課比較放大葉脈和小樹模型。","example":"The leaf's pattern was akin to the branches of a small tree.","example_zh":"葉片紋理類似小樹枝幹。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/akin-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-allegiance-01-v1","level":"senior","word":"allegiance","sort_order":1,"sense":"忠誠","alt_zh":"高中生在歷史文學展看虛構成年騎士莊重向王國宣誓的畫作，無武器。","example":"The story explored a knight's allegiance to the kingdom.","example_zh":"故事探討騎士對王國的忠誠。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/allegiance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-aloof-01-v1","level":"senior","word":"aloof","sort_order":1,"sense":"冷漠的","alt_zh":"高中戲劇課中一位虛構成年角色獨坐舞臺一側，其他人友善邀請加入。","example":"The aloof character stayed apart from the cheerful group.","example_zh":"冷漠角色與歡樂人群保持距離。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aloof-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-amenable-01-v1","level":"senior","word":"amenable","sort_order":1,"sense":"順從的；願配合的","alt_zh":"兩組高中社團與成年老師友善移動無字時段圖卡，達成共識。","example":"The club was amenable to changing the rehearsal schedule.","example_zh":"社團願意配合調整排練時間。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/amenable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-amicable-01-v1","level":"senior","word":"amicable","sort_order":1,"sense":"友善的","alt_zh":"成年社區代表在花園模型旁微笑握手，高中志工旁觀。","example":"The discussion ended with an amicable agreement.","example_zh":"討論以友善協議結束。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/amicable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-antithesis-01-v1","level":"senior","word":"antithesis","sort_order":1,"sense":"對立面","alt_zh":"同一城鎮街景中，成年導覽員帶高中生看活躍市集和旁邊安靜圖書館。","example":"The noisy market was the antithesis of the quiet library.","example_zh":"喧鬧市集與安靜圖書館恰好相反